.mobile-controls .interact-button.ready{opacity:1;box-shadow:0 0 18px rgba(200,241,106,.24)}
.mobile-controls .interact-button:disabled{cursor:default}
.story-panel{position:fixed;inset:0;z-index:13;display:none;align-items:center;justify-content:center;padding:24px;background:rgba(8,13,14,.62);backdrop-filter:blur(5px)}
.story-panel.open{display:flex}.story-box{width:min(440px,92vw);padding:28px 32px;background:rgba(17,25,26,.97);border:1px solid rgba(212,224,214,.2);border-left:2px solid var(--lime);box-shadow:0 18px 90px rgba(0,0,0,.5)}
.story-box>small{font:9px 'DM Mono',monospace;letter-spacing:.18em;color:var(--lime)}.story-box h2{font-size:clamp(28px,6vw,42px);line-height:.95;margin:12px 0;letter-spacing:.05em}.story-box p{font-size:16px;line-height:1.45;color:#bac4bc;margin:0}.story-box button{display:flex;justify-content:space-between;align-items:center;width:100%;height:44px;margin-top:22px;padding:0 14px;border:0;background:var(--lime);color:#18201d;font:700 11px 'DM Mono',monospace;letter-spacing:.08em;cursor:pointer}.story-box .pause-foot{margin-top:16px}
.damage-overlay{position:fixed;inset:0;z-index:3;pointer-events:none;opacity:0;background:radial-gradient(ellipse,transparent 42%,rgba(211,50,37,.58) 100%);transition:opacity .1s}
@media(max-width:700px){.objective{top:48px;min-width:210px}.objective small{font-size:8px}.objective strong{font-size:11px}.wave-card{top:91px}.bottom-hud{bottom:165px}.mission-note{display:none}.mobile-controls .interact-button{right:18px;bottom:128px}.fire-button{right:19px;bottom:34px}.reload-button{right:101px;bottom:44px}.story-box{padding:24px 23px}.controls{max-width:95%}.briefing-details{flex-wrap:wrap}.briefing-details div:nth-child(2){max-width:45%}}

